import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"原生 Agent Runtime","description":"Hearth 如何把 Pi 式单 Agent 内核升级为通用执行内核，并在任务边界内统一权限、上下文、委派、Worktree、MCP、检查点和恢复。","frontmatter":{"title":"原生 Agent Runtime","description":"Hearth 如何把 Pi 式单 Agent 内核升级为通用执行内核，并在任务边界内统一权限、上下文、委派、Worktree、MCP、检查点和恢复。","outline":[2,3]},"headers":[],"relativePath":"design/native-agent-runtime.md","filePath":"design/native-agent-runtime.md","lastUpdated":1794373393000}'),r={name:"design/native-agent-runtime.md"};function n(i,t,l,c,s,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="原生-agent-runtime" tabindex="-1">原生 Agent Runtime <a class="header-anchor" href="#原生-agent-runtime" aria-label="Permalink to &quot;原生 Agent Runtime&quot;">​</a></h1><p class="lead">Hearth 的原生执行器不是一段“把任务发给模型”的提示词，而是一个可暂停、可恢复、受权限和预算约束的通用执行内核。它以 Pi 的简洁工具循环为起点，并借鉴 DeerFlow 的长任务编排和 OpenCode 的通用执行面，由 Hearth 自己实现，不引入这些项目的运行时。</p><h2 id="为什么自研-runtime" tabindex="-1">为什么自研 Runtime <a class="header-anchor" href="#为什么自研-runtime" aria-label="Permalink to &quot;为什么自研 Runtime&quot;">​</a></h2><p>聊天模型可以回答问题，但不能直接证明工作真的完成。要形成闭环，系统必须自己保存消息、执行工具、累计用量、限制权限、写入检查点，并在缺少产物时继续补齐。把这些职责交给外部 CLI 会让任务状态、权限和恢复语义分裂在两个进程里。</p><p>Hearth 因此保留两层执行能力：</p><table tabindex="0"><thead><tr><th>执行器</th><th>定位</th><th>典型任务</th></tr></thead><tbody><tr><td><code>native</code></td><td>通用单 Agent，直接调用当前聊天模型和内置工具</td><td>整理资料、生成文档、分析网页、简单文件处理</td></tr><tr><td><code>codex</code></td><td>面向代码仓库和多文件工程的专长执行器</td><td>修复项目错误、修改代码、运行测试、提交改动</td></tr></tbody></table><p>原生执行器是默认的通用路径。只有明确属于仓库或工程工作时，路由器才选择 Codex；两者不会在失败后静默互换。</p><h2 id="内核形态" tabindex="-1">内核形态 <a class="header-anchor" href="#内核形态" aria-label="Permalink to &quot;内核形态&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务 + 用户补充</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span> 系统提示 + 消息历史</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span> 模型流式回合 ──→ 文本回答 / 工具调用</span></span>
<span class="line"><span>      ↓                    ↓</span></span>
<span class="line"><span> Token 与预算累计      执行受权限约束的工具</span></span>
<span class="line"><span>      ↓                    ↓</span></span>
<span class="line"><span>  写入检查点 ←──── 工具结果回填</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span> 完成 / 暂停等待输入 / 预算耗尽 / 取消</span></span></code></pre></div><p>每轮只做一件事：模型返回内容与工具调用，Runtime 执行工具并把结果作为下一条消息回填。模型只输出文本不再被视为完成；任务完成的唯一可信信号是模型调用 <code>finish_task</code>，以及声明的产物确实存在且非空。</p><h2 id="消息与协议" tabindex="-1">消息与协议 <a class="header-anchor" href="#消息与协议" aria-label="Permalink to &quot;消息与协议&quot;">​</a></h2><p><code>@hearth/model-client</code> 负责四种协议：OpenAI Chat Completions、OpenAI Responses、Anthropic Messages 和 Gemini。<code>model-agent.ts</code> 把它们统一成同一种流式 Agent 回合：文本增量、工具调用、工具参数拼接、结束原因和用量。</p><p>这样更换模型提供商不会改变 Runtime 的工具循环，也不需要为每家模型复制一套调度逻辑。原生执行器要求模型支持工具调用；不支持时直接给出明确错误，不伪装成成功。</p><h2 id="通用工具面" tabindex="-1">通用工具面 <a class="header-anchor" href="#通用工具面" aria-label="Permalink to &quot;通用工具面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>默认边界</th></tr></thead><tbody><tr><td><code>read_file</code>、<code>read_document</code>、<code>list_files</code>、<code>search_text</code></td><td>读取文本、PDF、DOCX、XLSX、CSV、JSON 和 HTML</td><td>只能访问任务工作区与授权目录；文档大小和返回字符数有上限</td></tr><tr><td><code>glob</code>、<code>grep</code></td><td>按模式定位文件，用 RE2 兼容正则搜索 include/exclude 范围</td><td>有结果数、文件大小、扫描时长预算；拒绝路径逃逸</td></tr><tr><td><code>write_file</code>、<code>edit_file</code>、<code>apply_patch</code></td><td>生成、预览修改、原子应用补丁、移动和删除文件</td><td><code>edit_file</code> 支持 dry-run 差异预览；补丁先全量预校验，再一次性写入，避免部分成功</td></tr><tr><td><code>write_spreadsheet</code>、<code>write_document</code></td><td>生成 XLSX/CSV 和 DOCX 办公文件</td><td>只能写入授权目录，并经过文件动作审批</td></tr><tr><td><code>shell</code></td><td>运行必要检查命令</td><td>只在工作区任务中授权；保存完整输出到任务日志，只回填尾部；超时杀死整个进程树</td></tr><tr><td><code>fetch_url</code>、<code>web_search</code></td><td>读取网页或执行 Tavily/SearXNG 搜索</td><td>网络默认关闭；研究任务显式授予公共网络能力；每次抓取仍审批，并检查重定向、DNS 和私网地址</td></tr><tr><td><code>load_skill</code>、<code>read_skill_resource</code></td><td>按需加载已采纳技能和技能包资源</td><td>提示词只注入索引；加载时校验内容哈希和任务权限；资源路径不能越出技能包</td></tr><tr><td><code>delegate_task</code></td><td>有界委派只读或隔离写子任务</td><td>新上下文、单层、串行、每任务最多两个；不自动合并</td></tr><tr><td><code>mcp__&lt;serverId&gt;__&lt;toolName&gt;</code></td><td>调用本地 stdio MCP 工具</td><td>只注入已启用且探测成功的服务器；Schema 校验、结果限长、密钥脱敏和逐次审批</td></tr><tr><td><code>ask_user</code></td><td>缺少关键信息时暂停</td><td>进入 <code>waiting_input</code>，不继续猜测</td></tr><tr><td><code>finish_task</code></td><td>声明完成并给出中文总结</td><td>纯文本回复不算完成；仍需通过产物检查</td></tr></tbody></table><p>符号链接逃逸、路径越界、私有地址和未授权域名都在工具层拒绝。权限按任务固定，不在执行过程中由模型自行扩大。</p><h2 id="上下文与执行稳定性" tabindex="-1">上下文与执行稳定性 <a class="header-anchor" href="#上下文与执行稳定性" aria-label="Permalink to &quot;上下文与执行稳定性&quot;">​</a></h2><p>模型档案保存 <code>contextWindowTokens</code> 和 <code>maxOutputTokens</code>。旧配置迁移为 128K 上下文窗口和 8K 最大输出，设置页可以修改。Runtime 按上下文窗口减去 <code>max(16K, 15%)</code> 的预留空间，并保留约 20K 近期 Token 触发压缩。</p><p>压缩只从完整回合边界开始，绝不拆散 assistant 工具调用和对应 tool 结果。压缩前先保留完整回合，再生成摘要，并把压缩结果写入检查点；摘要失败时回退到安全截断，任务仍可继续。恢复后的消息序列再次超限时也会重新压缩。</p><p>执行错误只对 429、5xx 和网络错误做两次瞬态重试；4xx、用户取消和权限拒绝不重试。上下文超限先强制压缩再重试。相同工具名和参数连续重复时只提示一次，超过阈值后失败，避免无限循环。</p><h2 id="技能、项目与-worktree" tabindex="-1">技能、项目与 Worktree <a class="header-anchor" href="#技能、项目与-worktree" aria-label="Permalink to &quot;技能、项目与 Worktree&quot;">​</a></h2><p>已采纳技能默认只以索引进入提示词，正文通过 <code>load_skill</code> 按需读取。加载会校验内容哈希、审计结果和任务权限；技能只能提供执行方法，不能扩张路径、网络、工具或审批权限。<code>read_skill_resource</code> 只允许读取技能包内列出的相对资源。</p><p>本地项目必须指向 Git 根目录和存在的分支。项目任务默认使用 <code>native</code> 与 <code>workspace</code>，并在 <code>hearth/&lt;task-id&gt;</code> 分支上创建独立 Worktree；任务恢复复用同一 Worktree。成功和失败都保留分支与目录，只有用户明确清理且工作区干净时才删除，脏目录拒绝清理。GitHub 任务继续默认走 Codex，不会静默切换执行器。</p><h2 id="有界委派" tabindex="-1">有界委派 <a class="header-anchor" href="#有界委派" aria-label="Permalink to &quot;有界委派&quot;">​</a></h2><p><code>delegate_task</code> 使用全新消息上下文，只允许只读或隔离写。只读子代理移除写入工具和 Shell；隔离写从父 Worktree 当前 HEAD 创建子 Worktree，完成后提交并返回分支与提交号。父任务检查后才能手动 cherry-pick，系统不会自动合并。</p><p>子代理单层嵌套、串行执行、每个父任务最多两个，禁止继续委派和 MCP。子代理用量计入父任务预算与用量；任一限制越界都明确失败。</p><h2 id="本地-mcp" tabindex="-1">本地 MCP <a class="header-anchor" href="#本地-mcp" aria-label="Permalink to &quot;本地 MCP&quot;">​</a></h2><p>首版只支持本地 stdio 服务器。服务器命令、参数和环境变量由用户显式配置；环境变量使用现有 <code>SecretBox</code> 加密，视图只暴露键名，不继承 Hearth 模型密钥或任意父进程密钥。探测失败、启动崩溃和调用超时彼此隔离，不拖垮任务进程。</p><p>工具统一命名为 <code>mcp__&lt;serverId&gt;__&lt;toolName&gt;</code>。发现时检查名称、描述、工具数量、Schema 和跨服务器冲突；调用前再次校验 JSON Schema，并限制结果大小。工具输出、错误和服务器 stderr 都会脱敏。</p><p>MCP 调用默认逐次进入现有工具审批，审批绑定服务器、工具名和参数摘要；只有完全权限模式自动放行并记录审计。系统不做自动重试，也不承诺 exactly-once；可能产生外部副作用的 MCP 工具仍需要用户理解其语义并自行决定是否调用。</p><h2 id="能力矩阵" tabindex="-1">能力矩阵 <a class="header-anchor" href="#能力矩阵" aria-label="Permalink to &quot;能力矩阵&quot;">​</a></h2><p>下表的判断来自公开能力和代码成熟度，不是共享基准结果。不能据此宣称 Hearth 已在数值上超过 Pi、DeerFlow 或 OpenCode。</p><table tabindex="0"><thead><tr><th>维度</th><th>Hearth native</th><th>Pi</th><th>DeerFlow</th><th>OpenCode</th></tr></thead><tbody><tr><td>通用编码执行面</td><td>glob/grep、原子编辑、Shell、办公文件、搜索、技能、子代理、本地 MCP 和 Worktree 已具备</td><td>核心文件工具和精简编码循环成熟</td><td>长任务中间件、沙箱、子代理、技能、记忆和延迟工具更完整</td><td>当前公开执行面最广；规则工具、编辑、Shell、技能、子代理、MCP、压缩和 Worktree 覆盖齐全</td></tr><tr><td>长时任务编排</td><td>有预算、检查点、恢复、目标验收和审批治理</td><td>以精简循环为主</td><td>长任务编排能力更强</td><td>通用执行强，但控制面不是 Hearth 的任务账本模型</td></tr><tr><td>上下文管理</td><td>按窗口 Token 触发、完整回合压缩、摘要失败回退、压缩后检查点</td><td>有会话树和压缩</td><td>有完整上下文中间件</td><td>压缩能力成熟</td></tr><tr><td>委派</td><td>单层、串行、最多两个、只读或隔离写、不自动合并</td><td>首版不作为重点</td><td>子代理和多阶段编排更强</td><td>子代理更成熟、覆盖更广</td></tr><tr><td>MCP</td><td>仅本地 stdio，逐次审批，崩溃隔离</td><td>不作为核心能力</td><td>不以 MCP 为核心参照</td><td>公开能力更完整</td></tr><tr><td>项目与 Worktree</td><td>本地 Git 项目注册、隔离 Worktree、手动清理</td><td>更偏精简编码范围</td><td>沙箱与长任务编排更强</td><td>Worktree 覆盖最完整</td></tr><tr><td>控制与证据</td><td>审批、效果记录、检查点、恢复、产物验证和任务治理最强</td><td>控制面较轻</td><td>治理模型不同</td><td>控制面较轻</td></tr></tbody></table><p>因此更准确的结论是：OpenCode 的通用执行面最完整，DeerFlow 的长时编排更强，Pi 在精简编码范围内更成熟；Hearth native 的控制面最强，执行面已经补齐到可做多文件编码、研究办公、技能复用、有界委派、本地 MCP 和本地项目 Worktree，但在 LSP、格式化器、远程 MCP、浏览器自动化、视觉理解和自动合并上仍有明显差距。</p><h2 id="预算、检查点与恢复" tabindex="-1">预算、检查点与恢复 <a class="header-anchor" href="#预算、检查点与恢复" aria-label="Permalink to &quot;预算、检查点与恢复&quot;">​</a></h2><p>每次原生运行都有四类预算：最大轮次、最大工具调用次数、最大 Token 和最大时长。超过预算会停止并返回可解释的结果，不继续消耗。</p><p>Runtime 在每个模型回合、每个工具步骤、等待输入和最终完成时写入检查点。检查点包含消息、用量、轮次和工具调用计数。恢复时：</p><ol><li>找到最近一次可恢复的检查点，复制当时的工作区。</li><li>恢复消息与预算计数，必要时把用户补充作为新的 <code>user</code> 消息追加。</li><li>从暂停位置继续，而不是从头重跑。</li><li>最终产物缺失时，带着上一轮 Agent 上下文补交，最多两轮；仍不满足则明确失败。</li></ol><p>检查点存放在隔离工作区的 <code>.hearth/checkpoints/</code> 下，任务详情只展示数量和折叠的技术信息，不把中间 JSON 当作用户产物。</p><h2 id="完成契约" tabindex="-1">完成契约 <a class="header-anchor" href="#完成契约" aria-label="Permalink to &quot;完成契约&quot;">​</a></h2><ul><li>通用与交付任务必须生成声明的产物，默认是 <code>result.md</code>。</li><li>工作区任务必须给出最终总结，并保留代码改动和测试证据。</li><li>中间 JSON、命令日志、检查点和运行时文件不进入用户产物列表。</li><li>声明的产物为空、执行器没有返回总结或预算耗尽，都不能标记为完成。</li><li>用户需要的最终结果出现在任务详情顶部；执行命令、检查点和内部事件收进折叠区域。</li></ul><h2 id="任务提案" tabindex="-1">任务提案 <a class="header-anchor" href="#任务提案" aria-label="Permalink to &quot;任务提案&quot;">​</a></h2><p>需要联网或读写工程工作区的任务，先在聊天中生成任务提案，而不是直接执行。提案说明执行器、任务类型、期望产物、网络域名和原因。用户确认后才创建任务并进入调度队列；拒绝则不产生任务。</p><p>普通通用任务可以直接派出。这样既保持“说一句话就开始”的简单交互，又让高权限动作有明确的用户授权点。</p><h2 id="当前边界" tabindex="-1">当前边界 <a class="header-anchor" href="#当前边界" aria-label="Permalink to &quot;当前边界&quot;">​</a></h2><ul><li>子代理只支持单层、串行、最多两个；不做并行团队、递归委派或自动合并。</li><li>MCP 只支持本地 stdio；不支持远程 HTTP、OAuth、托管多租户或工具级 exactly-once。</li><li>搜索默认关闭；公共网络能力不会绕过私网拦截和逐次抓取审批。</li><li>不支持浏览器自动化搜索、图片/扫描件视觉理解、PPTX、LSP、格式化器、Shell 后台会话和自动 cherry-pick。</li><li>执行使用当前聊天模型，不内置第二套“执行模型”；工作区任务优先在本地 Worktree 中执行。</li><li>不把中间步骤、内部 JSON 或终端输出当作交付结果。</li><li>没有共享基准，不声称已量化超过 Pi、DeerFlow 或 OpenCode；只按公开能力说明差距和已补齐范围。</li></ul>`,46)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
